import java.util.Arrays;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;

        int N = sc.nextInt();
        int K = sc.nextInt();

        int[] a = new int[N + 1];
        for (int i = 1; i <= N; i++) {
            a[i] = sc.nextInt();
        }

        Arrays.sort(a, 1, N + 1);

        final long INF = Long.MAX_VALUE / 4;
        long[] prev = new long[N + 1];
        long[] curr = new long[N + 1];

        for (int j = 1; j <= K; j++) {
            Arrays.fill(curr, INF);
            int limit = N - 3 * K + 3 * j - 1;

            for (int i = 1; i <= N; i++) {
                curr[i] = curr[i - 1];

                if (i >= 2 && i <= limit) {
                    long diff = a[i] - a[i - 1];
                    long cost = diff * diff;
                    long val = prev[i - 2] + cost;
                    if (val < curr[i]) {
                        curr[i] = val;
                    }
                }
            }

            long[] tmp = prev;
            prev = curr;
            curr = tmp;
        }

        System.out.println(prev[N]);
    }
}
```

